  "UPDATE trip_events e INNER JOIN trips t ON t.id=e.trip_id INNER JOIN trip_events s ON s.trip_id=e.trip_id AND s.event_type_id=1 SET e.value=JSON_SET(JSON_REMOVE(e.value,'$.creationAnchor','$.value'),'$.valueOffsetMilliseconds',TIMESTAMPDIFF(MICROSECOND,t.scheduled_start_time,TIMESTAMPADD(MICROSECOND,CAST(TIME_TO_SEC(JSON_UNQUOTE(JSON_EXTRACT(e.value,'$.value')))*1000000 AS SIGNED),CAST(REPLACE(REPLACE(SUBSTRING(JSON_UNQUOTE(JSON_EXTRACT(s.value,'$.creationAnchor')),1,23),'T',' '),'Z','') AS DATETIME(3)))) DIV 1000) WHERE e.event_type_id=7",
  "UPDATE trip_events e INNER JOIN trips t ON t.id=e.trip_id SET e.value=JSON_SET(JSON_REMOVE(e.value,'$.creationAnchor','$.creationTime','$.scheduledStart','$.scheduledStartTime','$.startTime'),\n '$.creationOffsetMilliseconds',COALESCE(JSON_EXTRACT(e.value,'$.creationOffsetMilliseconds'),TIMESTAMPDIFF(MICROSECOND,t.scheduled_start_time,TIMESTAMPADD(MICROSECOND,CAST(TIME_TO_SEC(JSON_UNQUOTE(JSON_EXTRACT(e.value,'$.creationTime')))*1000000 AS SIGNED),CAST(REPLACE(REPLACE(SUBSTRING(JSON_UNQUOTE(JSON_EXTRACT(e.value,'$.creationAnchor')),1,23),'T',' '),'Z','') AS DATETIME(3)))) DIV 1000),\n '$.startOffsetMilliseconds',e.offset_ms,'$.scheduledStartOffsetMilliseconds',0,'$.legacyWallClockData',IF(JSON_EXTRACT(e.value,'$.timelineVersion')=2,false,true),'$.timelineVersion',2) WHERE e.event_type_id=1",
