  "ALTER TABLE trips DROP CONSTRAINT chk_trips_time_order, DROP CONSTRAINT chk_trips_standard_time, DROP CONSTRAINT chk_trips_non_production, DROP INDEX idx_trips_user_start, DROP COLUMN start_time, DROP COLUMN end_time, DROP COLUMN non_production, DROP COLUMN break_only, MODIFY scheduled_start_time DATETIME(3) NOT NULL, MODIFY start_offset_ms BIGINT SIGNED NOT NULL, MODIFY end_offset_ms BIGINT SIGNED NOT NULL, MODIFY production ENUM('yes','no','break-only') NOT NULL DEFAULT 'yes', ADD KEY idx_trips_user_schedule (user_id,scheduled_start_time), ADD CONSTRAINT chk_trips_time_order CHECK (end_offset_ms>start_offset_ms), ADD CONSTRAINT chk_trips_standard_time CHECK ((production='break-only' AND standard_time_ms IS NULL AND counted_time_ms=0) OR (production IN ('yes','no') AND standard_time_ms IS NOT NULL AND standard_time_ms>0))",
