  "CREATE TRIGGER `audit_trips_add` AFTER INSERT ON `trips` FOR EACH ROW BEGIN\n IF @audit_user_id IS NULL OR @audit_change_id IS NULL OR CHAR_LENGTH(TRIM(@audit_change_id))=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Audit context is required'; END IF;\n SET @audit_sequence=COALESCE(@audit_sequence,0)+1;\n INSERT INTO `log` (`user_id`,`action`,`table_name`,`record_id`,`before_data`,`after_data`,`change_id`,`sequence`,`reversal_of`) VALUES\n (@audit_user_id,'add','trips',NEW.id,NULL,JSON_OBJECT('id',NEW.`id`,'user_id',NEW.`user_id`,'scheduled_start_time',NEW.`scheduled_start_time`,'start_offset_ms',NEW.`start_offset_ms`,'end_offset_ms',NEW.`end_offset_ms`,'standard_time_ms',NEW.`standard_time_ms`,'counted_time_ms',NEW.`counted_time_ms`,'production',NEW.`production`,'pending',NEW.`pending`,'client_token',NEW.`client_token`,'created_at',NEW.`created_at`),@audit_change_id,@audit_sequence,NULLIF(@audit_reversal_of,''));\nEND",
