  "CREATE TRIGGER `protect_trip_events_update` BEFORE UPDATE ON `trip_events` FOR EACH ROW BEGIN\n IF @trip_anchor_rebase_ms IS NULL OR NEW.offset_ms <> OLD.offset_ms + @trip_anchor_rebase_ms\n OR NOT(NEW.id <=> OLD.id) OR NOT(NEW.trip_id <=> OLD.trip_id) OR NOT(NEW.event_type_id <=> OLD.event_type_id)\n OR NOT(NEW.client_token <=> OLD.client_token) OR NOT(NEW.created_at <=> OLD.created_at)\n THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Trip events are immutable outside an audited anchor rebase'; END IF;\nEND"
